CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS organizations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, slug TEXT UNIQUE NOT NULL, type TEXT NOT NULL CHECK (type IN ('restaurant','hotel','school','church','event','retail','other')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS locations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), organization_id UUID NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name TEXT NOT NULL, address TEXT, public_slug TEXT UNIQUE NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS menus (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE, title TEXT NOT NULL DEFAULT 'Menu', description TEXT, published BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS menu_categories (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), menu_id UUID NOT NULL REFERENCES menus(id) ON DELETE CASCADE, name TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS menu_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), category_id UUID NOT NULL REFERENCES menu_categories(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT, price NUMERIC(12,2), currency CHAR(3) NOT NULL DEFAULT 'KES', image_url TEXT, available BOOLEAN NOT NULL DEFAULT true, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS agendas (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE, title TEXT NOT NULL, meeting_date DATE, venue TEXT, published BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agenda_items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), agenda_id UUID NOT NULL REFERENCES agendas(id) ON DELETE CASCADE, title TEXT NOT NULL, notes TEXT, presenter TEXT, duration_minutes INTEGER, sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS discovery_devices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), location_id UUID NOT NULL REFERENCES locations(id) ON DELETE CASCADE, device_type TEXT NOT NULL CHECK (device_type IN ('ble_beacon','qr','nfc')), identifier TEXT UNIQUE NOT NULL, target_url TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT true, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
